	ForkAlerts(context.Context, *QueryForkAlertsRequest) (*QueryForkAlertsResponse, error)
	// PartitionAlerts queries active partition alerts
	PartitionAlerts(context.Context, *QueryPartitionAlertsRequest) (*QueryPartitionAlertsResponse, error)
