	DoubleSignEvidences(context.Context, *QueryDoubleSignEvidencesRequest) (*QueryDoubleSignEvidencesResponse, error)
	// DowntimeInfractions queries downtime infractions
	DowntimeInfractions(context.Context, *QueryDowntimeInfractionsRequest) (*QueryDowntimeInfractionsResponse, error)
